import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { uploadFileToStorage } from '@/features/storage';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';

interface BrandFormData {
  name: string;
  slug: string;
  description: string;
  country: string;
  logoUrl: string;
}

interface BrandFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  isCreating: boolean;
  formData: BrandFormData;
  onFormChange: (data: BrandFormData) => void;
  /** Gọi với data đã sẵn sàng (có logoUrl sau khi upload nếu có file chọn). Cancel thì không upload. */
  onSave: (data: BrandFormData) => void;
}

export function BrandFormDialog({
  open,
  onOpenChange,
  isCreating,
  formData,
  onFormChange,
  onSave,
}: BrandFormDialogProps) {
  const { t } = useTranslation();
  const [selectedLogoFile, setSelectedLogoFile] = useState<File | null>(null);
  const [logoPreviewUrl, setLogoPreviewUrl] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);

  // Revoke object URL when cleanup (dialog close or file change)
  useEffect(() => {
    return () => {
      if (logoPreviewUrl) URL.revokeObjectURL(logoPreviewUrl);
    };
  }, [logoPreviewUrl]);

  // Reset pending file when dialog closes
  useEffect(() => {
    if (!open) {
      setSelectedLogoFile(null);
      if (logoPreviewUrl) {
        URL.revokeObjectURL(logoPreviewUrl);
        setLogoPreviewUrl(null);
      }
    }
  }, [open]); // eslint-disable-line react-hooks/exhaustive-deps -- only reset when open becomes false

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file) return;
    if (logoPreviewUrl) URL.revokeObjectURL(logoPreviewUrl);
    setSelectedLogoFile(file);
    setLogoPreviewUrl(URL.createObjectURL(file));
    // Xóa link/ảnh cũ: khi chọn ảnh mới thì bỏ URL cũ khỏi input, preview sẽ hiển thị ảnh vừa chọn.
    onFormChange({ ...formData, logoUrl: '' });
  };

  const handleDialogOpenChange = (next: boolean) => {
    if (!next) {
      setSelectedLogoFile(null);
      if (logoPreviewUrl) {
        URL.revokeObjectURL(logoPreviewUrl);
        setLogoPreviewUrl(null);
      }
    }
    onOpenChange(next);
  };

  const handleSaveClick = async () => {
    let finalLogoUrl = formData.logoUrl;
    if (selectedLogoFile) {
      setUploading(true);
      try {
        const ext = (
          selectedLogoFile.name.split('.').pop() || 'png'
        ).toLowerCase();
        const objectKey = `brands/${crypto.randomUUID()}.${ext}`;
        finalLogoUrl = await uploadFileToStorage(selectedLogoFile, objectKey);
      } finally {
        setUploading(false);
      }
    }
    onSave({ ...formData, logoUrl: finalLogoUrl });
  };

  const previewUrl = logoPreviewUrl ?? formData.logoUrl;

  return (
    <Dialog open={open} onOpenChange={handleDialogOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>
            {isCreating
              ? t('admin.brands.createDialog.title')
              : t('admin.brands.editDialog.title')}
          </DialogTitle>
          <DialogDescription className='sr-only'>
            {isCreating
              ? t(
                  'admin.brands.createDialog.description',
                  'Form to create a new brand'
                )
              : t(
                  'admin.brands.editDialog.description',
                  'Form to edit brand details'
                )}
          </DialogDescription>
        </DialogHeader>
        <div className='space-y-4'>
          <div className='space-y-2'>
            <Label>{t('admin.brands.form.name')}</Label>
            <Input
              value={formData.name}
              onChange={(e) =>
                onFormChange({ ...formData, name: e.target.value })
              }
            />
          </div>
          <div className='space-y-2'>
            <Label>{t('admin.brands.form.slug')}</Label>
            <Input
              value={formData.slug}
              onChange={(e) =>
                onFormChange({ ...formData, slug: e.target.value })
              }
            />
          </div>
          <div className='space-y-2'>
            <Label>{t('admin.brands.form.country')}</Label>
            <Input
              value={formData.country}
              onChange={(e) =>
                onFormChange({ ...formData, country: e.target.value })
              }
              placeholder={t('admin.brands.form.selectCountry')}
            />
          </div>
          <div className='space-y-2'>
            <Label>{t('admin.brands.form.logoUrl')}</Label>
            <div className='flex flex-wrap items-center gap-2'>
              <Input
                value={formData.logoUrl}
                onChange={(e) =>
                  onFormChange({ ...formData, logoUrl: e.target.value })
                }
                placeholder='https://... or upload file'
                className='flex-1 min-w-0'
              />
              <label className='inline-flex h-9 cursor-pointer items-center justify-center rounded-md border border-input bg-background px-4 py-2 text-sm font-medium ring-offset-background hover:bg-accent hover:text-accent-foreground disabled:pointer-events-none disabled:opacity-50'>
                <input
                  type='file'
                  accept='image/*'
                  className='sr-only'
                  onChange={handleFileSelect}
                  disabled={uploading}
                />
                {uploading
                  ? t('common.uploading')
                  : t('admin.brands.form.uploadLogo')}
              </label>
            </div>
            <div className='mt-1 flex items-center gap-2'>
              <div className='relative flex h-20 w-20 shrink-0 items-center justify-center overflow-hidden rounded border bg-muted'>
                {previewUrl ? (
                  <>
                    <img
                      src={previewUrl}
                      alt='Logo preview'
                      className='h-full w-full object-contain'
                      onError={(e) => {
                        e.currentTarget.style.display = 'none';
                        const placeholder = e.currentTarget.nextElementSibling;
                        if (placeholder)
                          (placeholder as HTMLElement).classList.remove(
                            'hidden'
                          );
                      }}
                    />
                    <span
                      className='absolute inset-0 hidden flex items-center justify-center text-xs text-muted-foreground'
                      aria-hidden
                    >
                      {t('admin.brands.form.noImage', 'No image')}
                    </span>
                  </>
                ) : (
                  <span className='text-xs text-muted-foreground'>
                    {t('admin.brands.form.noImage', 'No image')}
                  </span>
                )}
              </div>
              {selectedLogoFile && (
                <span className='text-xs text-muted-foreground'>
                  {t(
                    'admin.brands.form.logoPreviewHint',
                    'Preview – upload when you Save'
                  )}
                </span>
              )}
            </div>
          </div>
          <div className='space-y-2'>
            <Label>{t('admin.brands.form.description')}</Label>
            <Textarea
              value={formData.description}
              onChange={(e) =>
                onFormChange({ ...formData, description: e.target.value })
              }
              rows={3}
            />
          </div>
        </div>
        <DialogFooter>
          <Button
            variant='outline'
            onClick={() => handleDialogOpenChange(false)}
          >
            {t('common.cancel')}
          </Button>
          <Button onClick={handleSaveClick} disabled={uploading}>
            {uploading ? t('common.uploading') : t('common.save')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Separator } from '@/components/ui/separator';
import { Heart, ShoppingCart, Minus, Plus, Share2 } from 'lucide-react';

export interface ProductImage {
  id: string;
  url: string;
  alt: string;
}

export interface ProductSize {
  value: string;
  label: string;
  inStock?: boolean;
}

export interface ProductVariant {
  id: string;
  size: string;
  color: string;
  quantity: number;
  imageUrls: string[];
}

export interface ProductDetailProps {
  id: string;
  name: string;
  brand: string;
  price: number;
  originalPrice?: number;
  description: string;
  images: ProductImage[]; // Base images from shoe
  variants: ProductVariant[];
  sizes?: ProductSize[];
  rating?: number;
  reviewCount?: number;
  isSale?: boolean;
  isNew?: boolean;
  specifications?: { label: string; value: string }[];
  onAddToCart?: (
    id: string,
    size: string,
    color: string,

    quantity: number
  ) => void;
  onAddToWishlist?: (id: string) => void;
  onShare?: (id: string) => void;
}

export function ProductDetail({
  id,
  name,
  brand,
  price,
  originalPrice,
  description,
  images,
  variants,
  rating,
  reviewCount,
  isSale,
  specifications = [],
  onAddToCart,
  onAddToWishlist,
  onShare,
}: ProductDetailProps) {
  const [selectedSize, setSelectedSize] = useState<string | null>(null);
  const [selectedColor, setSelectedColor] = useState<string | null>(null);

  const [quantity, setQuantity] = useState(1);
  const [activeImageIndex, setActiveImageIndex] = useState(0);

  // Derive unique sizes
  const uniqueSizes = Array.from(new Set(variants.map((v) => v.size))).sort();

  // Derive colors available for the selected size
  const availableColors = selectedSize
    ? variants.filter((v) => v.size === selectedSize).map((v) => v.color)
    : [];

  // Find the selected variant
  const selectedVariant = variants.find(
    (v) => v.size === selectedSize && v.color === selectedColor
  );

  // Combine shoe images and all variant images for a single horizontal gallery
  // Each image will have a unique stable ID to avoid re-renders
  const allImages = [
    ...images.map((img) => ({ ...img, type: 'shoe' as const })),
    ...variants.flatMap((v) =>
      v.imageUrls.map((url, i) => ({
        id: `variant-${v.id}-${i}`,
        url,
        alt: `${name} ${v.color}`,
        type: 'variant' as const,
        variantId: v.id,
      }))
    ),
  ];

  const handleSizeSelect = (size: string) => {
    setSelectedSize(size);
    setSelectedColor(null);
    setQuantity(1);
  };

  const handleColorSelect = (color: string) => {
    setSelectedColor(color);
    setQuantity(1);

    // When color is selected, find the first image of this variant and scroll to it
    const variant = variants.find(
      (v) => v.size === selectedSize && v.color === color
    );
    if (variant && variant.imageUrls.length > 0) {
      const firstImageIndex = allImages.findIndex(
        (img) =>
          img.type === 'variant' &&
          'variantId' in img &&
          img.variantId === variant.id
      );
      if (firstImageIndex !== -1) {
        setActiveImageIndex(firstImageIndex);
      }
    }
  };

  const handleAddToCart = () => {
    if (selectedSize && selectedColor) {
      onAddToCart?.(id, selectedSize, selectedColor, quantity);
    }
  };

  const maxQuantity = selectedVariant?.quantity || 0;

  const discount = originalPrice
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0;

  return (
    <div className='grid gap-8 lg:grid-cols-2'>
      {/* Images Gallery */}
      <div className='space-y-4'>
        <div className='relative aspect-square overflow-hidden rounded-lg bg-muted'>
          <img
            src={allImages[activeImageIndex]?.url}
            alt={allImages[activeImageIndex]?.alt}
            className='h-full w-full object-contain'
          />
          <div className='absolute left-4 top-4 flex flex-col gap-2'>
            {isSale && discount > 0 && (
              <Badge variant='destructive'>-{discount}%</Badge>
            )}
          </div>
        </div>
        <div className='flex gap-2 overflow-x-auto pb-2'>
          {allImages.map((image, index) => (
            <button
              key={image.id}
              onClick={() => setActiveImageIndex(index)}
              className={`relative h-20 w-20 flex-shrink-0 overflow-hidden rounded-md border-2 transition-colors ${
                index === activeImageIndex
                  ? 'border-primary'
                  : 'border-transparent hover:border-muted-foreground/50'
              }`}
            >
              <img
                src={image.url}
                alt={image.alt}
                className='h-full w-full object-contain'
              />
            </button>
          ))}
        </div>
      </div>

      {/* Product Details */}
      <div className='space-y-6'>
        <div>
          <p className='text-sm text-muted-foreground'>{brand}</p>
          <h1 className='mt-1 text-3xl font-bold'>{name}</h1>
          {rating !== undefined && (
            <div className='mt-2 flex items-center gap-2'>
              <div className='flex items-center'>
                {[...Array(5)].map((_, i) => (
                  <span
                    key={i}
                    className={
                      i < Math.round(rating) ? 'text-yellow-500' : 'text-muted'
                    }
                  >
                    ★
                  </span>
                ))}
              </div>
              <span className='text-sm text-muted-foreground'>
                {rating.toFixed(1)} ({reviewCount} reviews)
              </span>
            </div>
          )}
        </div>

        <div className='flex items-baseline gap-3'>
          <span className='text-3xl font-bold'>
            {new Intl.NumberFormat('vi-VN', {
              style: 'currency',
              currency: 'VND',
            }).format(price)}
          </span>
          {originalPrice && originalPrice > price && (
            <span className='text-xl text-muted-foreground line-through'>
              {new Intl.NumberFormat('vi-VN', {
                style: 'currency',
                currency: 'VND',
              }).format(originalPrice)}
            </span>
          )}
        </div>

        <Separator />

        {/* Color (optional) */}
        {availableColors.length > 0 && !selectedSize && (
          <div>
            <h3 className='mb-3 font-medium'>Color</h3>
            <div className='flex flex-wrap gap-2'>
              {availableColors.map((color) => (
                <Button
                  key={color}
                  variant={selectedColor === color ? 'default' : 'outline'}
                  size='sm'
                  onClick={() => handleColorSelect(color)}
                >
                  {color}
                </Button>
              ))}
            </div>
          </div>
        )}

        {/* Size Selection */}
        <div className='space-y-3'>
          <h3 className='font-medium'>Kích thước (Size)</h3>
          <div className='flex flex-wrap gap-2'>
            {uniqueSizes.map((size) => {
              const hasStockForSize = variants
                .filter((v) => v.size === size)
                .some((v) => v.quantity > 0);
              return (
                <Button
                  key={size}
                  variant={selectedSize === size ? 'default' : 'outline'}
                  size='sm'
                  disabled={!hasStockForSize}
                  onClick={() => handleSizeSelect(size)}
                  className='min-w-[3rem]'
                >
                  {size}
                </Button>
              );
            })}
          </div>
        </div>

        {/* Color Selection */}
        {selectedSize && (
          <div className='space-y-3 animate-in fade-in slide-in-from-top-1'>
            <h3 className='font-medium'>Màu sắc</h3>
            <div className='flex flex-wrap gap-2'>
              {availableColors.map((color) => {
                const variant = variants.find(
                  (v) => v.size === selectedSize && v.color === color
                );
                const isOutOfStock = (variant?.quantity || 0) <= 0;
                return (
                  <Button
                    key={color}
                    variant={selectedColor === color ? 'default' : 'outline'}
                    size='sm'
                    disabled={isOutOfStock}
                    onClick={() => handleColorSelect(color)}
                  >
                    {color}
                    {isOutOfStock && ' (Hết hàng)'}
                  </Button>
                );
              })}
            </div>
          </div>
        )}

        {/* Stock Status & Quantity */}
        <div className='space-y-3'>
          <div className='flex items-center justify-between'>
            <h3 className='font-medium'>Số lượng</h3>
            {selectedVariant && (
              <span className='text-sm text-muted-foreground'>
                Còn lại: {selectedVariant.quantity} sản phẩm
              </span>
            )}
          </div>
          <div className='flex items-center gap-2'>
            <Button
              variant='outline'
              size='icon'
              onClick={() => setQuantity(Math.max(1, quantity - 1))}
              disabled={quantity <= 1 || !selectedVariant}
            >
              <Minus className='h-4 w-4' />
            </Button>
            <span className='w-12 text-center font-medium'>{quantity}</span>
            <Button
              variant='outline'
              size='icon'
              onClick={() => setQuantity(Math.min(maxQuantity, quantity + 1))}
              disabled={quantity >= maxQuantity || !selectedVariant}
            >
              <Plus className='h-4 w-4' />
            </Button>
          </div>
        </div>

        {/* Actions */}
        <div className='flex flex-col gap-3 sm:flex-row pt-2'>
          <Button
            size='lg'
            className='flex-1'
            disabled={!selectedVariant || maxQuantity <= 0}
            onClick={handleAddToCart}
          >
            <ShoppingCart className='mr-2 h-5 w-5' />
            Thêm vào giỏ hàng
          </Button>
          <Button
            size='lg'
            variant='outline'
            onClick={() => onAddToWishlist?.(id)}
          >
            <Heart className='mr-2 h-5 w-5' />
            Yêu thích
          </Button>
          <Button size='lg' variant='ghost' onClick={() => onShare?.(id)}>
            <Share2 className='h-5 w-5' />
          </Button>
        </div>

        <Separator />

        {/* Tabs */}
        <Tabs defaultValue='description'>
          <TabsList className='w-full justify-start'>
            <TabsTrigger value='description'>Mô tả</TabsTrigger>
            <TabsTrigger value='specifications'>Thông số kĩ thuật</TabsTrigger>
          </TabsList>
          <TabsContent value='description' className='mt-4'>
            <p className='text-muted-foreground leading-relaxed'>
              {description}
            </p>
          </TabsContent>
          <TabsContent value='specifications' className='mt-4'>
            {specifications.length > 0 ? (
              <dl className='grid grid-cols-1 gap-x-4 gap-y-2 sm:grid-cols-2'>
                {specifications.map((spec) => (
                  <div key={spec.label} className='border-b pb-2 sm:border-0'>
                    <dt className='text-sm text-muted-foreground'>
                      {spec.label}
                    </dt>
                    <dd className='font-medium'>{spec.value}</dd>
                  </div>
                ))}
              </dl>
            ) : (
              <p className='text-muted-foreground'>
                Chưa có thông số chi tiết.
              </p>
            )}
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

export default ProductDetail;

import { useState } from 'react';
import { Star } from 'lucide-react';
import { cn } from '@/lib/utils';

export interface RatingProps {
  value?: number;
  max?: number;
  onChange?: (value: number) => void;
  readonly?: boolean;
  size?: 'sm' | 'md' | 'lg';
  showValue?: boolean;
}

const sizeClasses = {
  sm: 'h-4 w-4',
  md: 'h-5 w-5',
  lg: 'h-6 w-6',
};

export function Rating({
  value = 0,
  max = 5,
  onChange,
  readonly = false,
  size = 'md',
  showValue = false,
}: RatingProps) {
  const [hoverValue, setHoverValue] = useState<number | null>(null);

  const displayValue = hoverValue !== null ? hoverValue : value;

  return (
    <div className='flex items-center gap-1'>
      <div className='flex'>
        {Array.from({ length: max }).map((_, index) => {
          const starValue = index + 1;
          const isFilled = starValue <= displayValue;
          const isHalf = !isFilled && starValue - 0.5 <= displayValue;

          return (
            <button
              key={index}
              type='button'
              disabled={readonly}
              onClick={() => !readonly && onChange?.(starValue)}
              onMouseEnter={() => !readonly && setHoverValue(starValue)}
              onMouseLeave={() => !readonly && setHoverValue(null)}
              className={cn(
                'relative transition-colors',
                readonly ? 'cursor-default' : 'cursor-pointer hover:scale-110'
              )}
            >
              <Star
                className={cn(
                  sizeClasses[size],
                  'transition-colors',
                  isFilled
                    ? 'fill-yellow-400 text-yellow-400'
                    : isHalf
                      ? 'fill-yellow-400/50 text-yellow-400'
                      : 'fill-muted text-muted-foreground/30'
                )}
              />
            </button>
          );
        })}
      </div>
      {showValue && (
        <span className='ml-1 text-sm text-muted-foreground'>
          {value.toFixed(1)}
        </span>
      )}
    </div>
  );
}

export default Rating;

