import { useEffect, useRef, useState } from 'react';

import { recordAudio } from '@/lib/audio-utils';

interface UseAudioRecordingOptions {
  transcribeAudio?: (blob: Blob) => Promise<string>;
  onTranscriptionComplete?: (text: string) => void;
}

export function useAudioRecording({
  transcribeAudio,
  onTranscriptionComplete,
}: UseAudioRecordingOptions) {
  const [isListening, setIsListening] = useState(false);
  const [isSpeechSupported, setIsSpeechSupported] = useState(!!transcribeAudio);
  const [isRecording, setIsRecording] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [audioStream, setAudioStream] = useState<MediaStream | null>(null);
  const activeRecordingRef = useRef<any>(null);

  useEffect(() => {
    const checkSpeechSupport = async () => {
      const hasMediaDevices = !!(
        navigator.mediaDevices && navigator.mediaDevices.getUserMedia
      );
      setIsSpeechSupported(hasMediaDevices && !!transcribeAudio);
    };

    checkSpeechSupport();
  }, [transcribeAudio]);

  const stopRecording = async () => {
    setIsRecording(false);
    setIsTranscribing(true);
    try {
      // First stop the recording to get the final blob
      recordAudio.stop();
      // Wait for the recording promise to resolve with the final blob
      const recording = await activeRecordingRef.current;
      if (transcribeAudio) {
        const text = await transcribeAudio(recording);
        onTranscriptionComplete?.(text);
      }
    } catch (error) {
      console.error('Error transcribing audio:', error);
    } finally {
      setIsTranscribing(false);
      setIsListening(false);
      if (audioStream) {
        audioStream.getTracks().forEach((track) => track.stop());
        setAudioStream(null);
      }
      activeRecordingRef.current = null;
    }
  };

  const toggleListening = async () => {
    if (!isListening) {
      try {
        setIsListening(true);
        setIsRecording(true);
        // Get audio stream first
        const stream = await navigator.mediaDevices.getUserMedia({
          audio: true,
        });
        setAudioStream(stream);

        // Start recording with the stream
        activeRecordingRef.current = recordAudio(stream);
      } catch (error) {
        console.error('Error recording audio:', error);
        setIsListening(false);
        setIsRecording(false);
        if (audioStream) {
          audioStream.getTracks().forEach((track) => track.stop());
          setAudioStream(null);
        }
      }
    } else {
      await stopRecording();
    }
  };

  return {
    isListening,
    isSpeechSupported,
    isRecording,
    isTranscribing,
    audioStream,
    toggleListening,
    stopRecording,
  };
}

import { useState, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { type Message } from '@/components/ui/chat-message';
import { sendChat } from '@/features/ai/api';

export function useChat() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { t } = useTranslation();

  const handleInputChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      setInput(e.target.value);
    },
    []
  );

  const sendMessage = useCallback(
    async (question: string) => {
      if (!question.trim() || isLoading) return;

      const userMessage: Message = {
        id: `user-${Date.now()}`,
        role: 'user',
        content: question,
        createdAt: new Date(),
      };
      setMessages((prev) => [...prev, userMessage]);
      setIsLoading(true);
      setError(null);

      try {
        const chatData = await sendChat(question, { skipAuth: true });

        const assistantMessage: Message = {
          id: `assistant-${Date.now()}`,
          role: 'assistant',
          content: chatData.output,
          createdAt: new Date(),
        };
        setMessages((prev) => [...prev, assistantMessage]);
      } catch (err) {
        setError(
          t(
            'ai.chat.error.cannotConnect',
            'Không thể kết nối tới chatbot. Vui lòng thử lại.'
          )
        );
        console.error('Chat error:', err);

        const errorMessage: Message = {
          id: `error-${Date.now()}`,
          role: 'assistant',
          content: t(
            'ai.chat.error.generic',
            'Xin lỗi, đã có lỗi xảy ra. Vui lòng thử lại sau.'
          ),
          createdAt: new Date(),
        };
        setMessages((prev) => [...prev, errorMessage]);
      } finally {
        setIsLoading(false);
      }
    },
    [isLoading, t]
  );

  const append = useCallback(
    (message: { role: 'user'; content: string }) => {
      setInput('');
      void sendMessage(message.content);
    },
    [sendMessage]
  );

  const handleSubmit = useCallback(
    async (
      event?: { preventDefault?: () => void },
      _options?: { experimental_attachments?: FileList }
    ) => {
      event?.preventDefault?.();

      const question = input.trim();
      setInput('');
      if (!question) return;
      await sendMessage(question);
    },
    [input, sendMessage]
  );

  const stop = useCallback(() => {
    setIsLoading(false);
  }, []);

  return {
    messages,
    input,
    handleInputChange,
    handleSubmit,
    append,
    isLoading,
    error,
    stop,
    setMessages,
  };
}

