const sidebarMenuButtonVariants = cva(
  'peer/menu-button flex w-full items-center gap-2 overflow-hidden rounded-md p-2 text-left text-sm outline-hidden ring-sidebar-ring transition-[width,height,padding] hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 active:bg-sidebar-accent active:text-sidebar-accent-foreground disabled:pointer-events-none disabled:opacity-50 group-has-data-[sidebar=menu-action]/menu-item:pr-8 aria-disabled:pointer-events-none aria-disabled:opacity-50 data-[active=true]:bg-sidebar-accent data-[active=true]:font-medium data-[active=true]:text-sidebar-accent-foreground data-[state=open]:hover:bg-sidebar-accent data-[state=open]:hover:text-sidebar-accent-foreground group-data-[collapsible=icon]:size-8! group-data-[collapsible=icon]:p-2! [&>span:last-child]:truncate [&>svg]:size-4 [&>svg]:shrink-0',
  {
    variants: {
      variant: {
        default: 'hover:bg-sidebar-accent hover:text-sidebar-accent-foreground',
        outline:
          'bg-background shadow-[0_0_0_1px_hsl(var(--sidebar-border))] hover:bg-sidebar-accent hover:text-sidebar-accent-foreground hover:shadow-[0_0_0_1px_hsl(var(--sidebar-accent))]',
      },
      size: {
        default: 'h-8 text-sm',
        sm: 'h-7 text-xs',
        lg: 'h-12 text-sm group-data-[collapsible=icon]:p-0!',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  }
);

export function SidebarMenuButton({
  asChild = false,
  isActive = false,
  variant = 'default',
  size = 'default',
  tooltip,
  className,
  ...props
}: React.ComponentProps<'button'> & {
  asChild?: boolean;
  isActive?: boolean;
  tooltip?: string | React.ComponentProps<typeof TooltipContent>;
} & VariantProps<typeof sidebarMenuButtonVariants>) {
  const Comp = asChild ? Slot : 'button';
  const { isMobile, state } = useSidebar();

  const button = (
    <Comp
      data-slot='sidebar-menu-button'
      data-sidebar='menu-button'
      data-size={size}
      data-active={isActive}
      className={cn(sidebarMenuButtonVariants({ variant, size }), className)}
      {...props}
    />
  );

  if (!tooltip) {
    return button;
  }

  if (typeof tooltip === 'string') {
    tooltip = {
      children: tooltip,
    };
  }

  return (
    <Tooltip>
      <TooltipTrigger asChild>{button}</TooltipTrigger>
      <TooltipContent
        side='right'
        align='center'
        hidden={state !== 'collapsed' || isMobile}
        {...tooltip}
      />
    </Tooltip>
  );
}

import { Menu, X, ShoppingCart, Heart } from 'lucide-react';
import { useState } from 'react';
import { Link, NavLink, useNavigate } from 'react-router';
import { useTranslation } from 'react-i18next';
import { useQueryCart } from '@/features/cart';
import { useQueryWishlist } from '@/features/wishlist';
import { LanguageToggle } from '@/components/language-toggle';
import { ModeToggle } from '@/components/mode-toggle';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import { UserMenu } from './UserMenu';
import { useIsMobile } from '@/hooks/useMobile';

export function Header() {
  const { t } = useTranslation();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const isMobile = useIsMobile();
  const navigate = useNavigate();

  const isMenuOpen = isMobile && mobileMenuOpen;

  const { data: cartData } = useQueryCart();
  const { data: wishlistData } = useQueryWishlist();
  const cartItemCount = cartData?.totalQuantity ?? 0;
  const wishlistCount = wishlistData?.length ?? 0;

  const mainNavigation = [
    { to: '/', label: t('nav.home') },
    { to: '/products', label: t('nav.products', { defaultValue: 'Products' }) },
    { to: '/about', label: t('nav.about', { defaultValue: 'About' }) },
  ];

  const handleCartClick = () => navigate('/cart');
  const handleWishlistClick = () => navigate('/wishlist');

  return (
    <header className='sticky top-0 z-50 w-full border-b bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60'>
      <div className='mx-auto max-w-6xl px-4'>
        <div className='flex h-16 items-center justify-between'>
          <div className='flex items-center gap-6'>
            <Link className='flex items-center gap-2' to='/'>
              <span className='bg-gradient-to-r from-primary to-primary/70 bg-clip-text text-xl font-bold tracking-tight text-transparent'>
                {t('appName')}
              </span>
            </Link>

            <nav className='hidden md:flex'>
              <ul className='flex items-center gap-6'>
                {mainNavigation.map((item) => (
                  <li key={item.to}>
                    <NavLink
                      to={item.to}
                      className={({ isActive }) =>
                        cn(
                          'text-sm font-medium transition-colors hover:text-primary',
                          isActive
                            ? 'font-semibold text-primary'
                            : 'text-muted-foreground'
                        )
                      }
                      end={item.to === '/'}
                    >
                      {item.label}
                    </NavLink>
                  </li>
                ))}
              </ul>
            </nav>
          </div>

          <div className='flex items-center gap-2'>
            {/* Wishlist Button */}
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant='ghost'
                  size='icon'
                  className='relative hidden sm:flex'
                  onClick={handleWishlistClick}
                >
                  <Heart className='h-5 w-5' />
                  {wishlistCount > 0 && (
                    <Badge
                      variant='destructive'
                      className='absolute -right-1 -top-1 h-5 w-5 rounded-full p-0 text-xs'
                    >
                      {wishlistCount}
                    </Badge>
                  )}
                </Button>
              </TooltipTrigger>
              <TooltipContent>{t('nav.wishlist')}</TooltipContent>
            </Tooltip>

            {/* Cart Button */}
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant='ghost'
                  size='icon'
                  className='relative'
                  onClick={handleCartClick}
                >
                  <ShoppingCart className='h-5 w-5' />
                  {cartItemCount > 0 && (
                    <Badge
                      variant='destructive'
                      className='absolute -right-1 -top-1 h-5 w-5 rounded-full p-0 text-xs'
                    >
                      {cartItemCount}
                    </Badge>
                  )}
                </Button>
              </TooltipTrigger>
              <TooltipContent>{t('nav.cart')}</TooltipContent>
            </Tooltip>

            <UserMenu mobile={false} />
            <ModeToggle />
            <LanguageToggle />

            {isMobile && (
              <Button
                className='md:hidden'
                onClick={() => setMobileMenuOpen((v) => !v)}
                size='icon'
                variant='ghost'
                aria-label='Toggle menu'
              >
                {isMenuOpen ? (
                  <X className='h-5 w-5' />
                ) : (
                  <Menu className='h-5 w-5' />
                )}
              </Button>
            )}
          </div>
        </div>
      </div>

      {isMenuOpen && (
        <div className='md:hidden'>
          <div className='space-y-1 border-b px-4 py-3'>
            {mainNavigation.map((item) => (
              <NavLink
                key={item.to}
                to={item.to}
                className={({ isActive }) =>
                  cn(
                    'block rounded-md px-3 py-2 text-base font-medium',
                    isActive
                      ? 'bg-primary/10 text-primary'
                      : 'hover:bg-muted/50 hover:text-primary'
                  )
                }
                end={item.to === '/'}
                onClick={() => setMobileMenuOpen(false)}
              >
                {item.label}
              </NavLink>
            ))}
            <div className='mt-2 border-t pt-2'>
              <UserMenu mobile onAfterAction={() => setMobileMenuOpen(false)} />
            </div>
          </div>
        </div>
      )}
    </header>
  );
}

import {
  LogIn,
  LogOut,
  User,
  UserCircle,
  UserPlus,
  Package,
  Heart,
  ShoppingCart,
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useAuth } from 'react-oidc-context';
import { Link } from 'react-router';

import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

type UserMenuProps = {
  mobile?: boolean;
  onAfterAction?: () => void;
};

function getDisplayName(auth: ReturnType<typeof useAuth>) {
  if (!auth.user) return 'User';
  return (
    auth.user.profile.name ||
    auth.user.profile.preferred_username ||
    auth.user.profile.email ||
    'User'
  );
}

export function UserMenu({ mobile = false, onAfterAction }: UserMenuProps) {
  const auth = useAuth();
  const { t } = useTranslation();

  const handleLogin = () => {
    void auth.signinRedirect();
    onAfterAction?.();
  };

  const handleRegister = () => {
    // Keycloak supports `kc_action=register` to open the registration screen.
    // `extraQueryParams` is supported by oidc-client-ts via react-oidc-context.
    void auth.signinRedirect({
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      extraQueryParams: { kc_action: 'register' } as any,
    });
    onAfterAction?.();
  };

  const handleLogout = () => {
    void auth.signoutRedirect();
    onAfterAction?.();
  };

  if (auth.isLoading) {
    return mobile ? (
      <div className='flex items-center justify-center px-3 py-2'>
        <div className='h-5 w-5 animate-spin rounded-full border-2 border-primary border-t-transparent' />
      </div>
    ) : (
      <div className='h-8 w-8 animate-spin rounded-full border-2 border-primary border-t-transparent' />
    );
  }

  if (!auth.isAuthenticated || !auth.user) {
    return mobile ? (
      <div className='flex flex-col gap-2'>
        <Button
          onClick={handleLogin}
          className='w-full justify-start'
          size='sm'
        >
          <LogIn className='mr-2 h-4 w-4' />
          {t('auth.login', { defaultValue: 'Đăng nhập' })}
        </Button>
        <Button
          onClick={handleRegister}
          variant='outline'
          className='w-full justify-start'
          size='sm'
        >
          <UserPlus className='mr-2 h-4 w-4' />
          {t('auth.register', { defaultValue: 'Đăng ký' })}
        </Button>
      </div>
    ) : (
      <div className='flex items-center gap-2'>
        <Button onClick={handleLogin} size='sm' className='gap-2'>
          <LogIn className='h-4 w-4' />
          <span className='hidden sm:inline-block'>
            {t('auth.login', { defaultValue: 'Đăng nhập' })}
          </span>
        </Button>
        <Button
          onClick={handleRegister}
          size='sm'
          variant='outline'
          className='gap-2'
        >
          <UserPlus className='h-4 w-4' />
          <span className='hidden sm:inline-block'>
            {t('auth.register', { defaultValue: 'Đăng ký' })}
          </span>
        </Button>
      </div>
    );
  }

  const displayName = getDisplayName(auth);
  const profilePath = '/profile';

  return mobile ? (
    <>
      <div className='px-3 py-2 text-sm'>
        <p className='font-medium'>{displayName}</p>
        {auth.user.profile.email && (
          <p className='text-xs text-muted-foreground'>
            {auth.user.profile.email}
          </p>
        )}
      </div>
      <Button
        asChild
        variant='ghost'
        className='w-full justify-start'
        size='sm'
        onClick={onAfterAction}
      >
        <Link to={profilePath}>
          <UserCircle className='mr-2 h-4 w-4' />
          {t('auth.profile', { defaultValue: 'Hồ sơ' })}
        </Link>
      </Button>
      <Button
        asChild
        variant='ghost'
        className='w-full justify-start'
        size='sm'
        onClick={onAfterAction}
      >
        <Link to='/orders'>
          <Package className='mr-2 h-4 w-4' />
          {t('nav.orders', { defaultValue: 'Đơn hàng' })}
        </Link>
      </Button>
      <Button
        asChild
        variant='ghost'
        className='w-full justify-start'
        size='sm'
        onClick={onAfterAction}
      >
        <Link to='/wishlist'>
          <Heart className='mr-2 h-4 w-4' />
          {t('nav.wishlist', { defaultValue: 'Yêu thích' })}
        </Link>
      </Button>
      <Button
        asChild
        variant='ghost'
        className='w-full justify-start'
        size='sm'
        onClick={onAfterAction}
      >
        <Link to='/cart'>
          <ShoppingCart className='mr-2 h-4 w-4' />
          {t('nav.cart', { defaultValue: 'Giỏ hàng' })}
        </Link>
      </Button>
      <Button
        onClick={handleLogout}
        variant='outline'
        className='w-full justify-start'
        size='sm'
      >
        <LogOut className='mr-2 h-4 w-4' />
        {t('auth.logout', { defaultValue: 'Đăng xuất' })}
      </Button>
    </>
  ) : (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant='outline' size='sm' className='gap-2'>
          <User className='h-4 w-4' />
          <span className='hidden sm:inline-block'>{displayName}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align='end' className='w-56'>
        <DropdownMenuLabel>
          <div className='flex flex-col space-y-1'>
            <p className='text-sm font-medium leading-none'>
              {auth.user.profile.name || 'User'}
            </p>
            {auth.user.profile.email && (
              <p className='text-xs leading-none text-muted-foreground'>
                {auth.user.profile.email}
              </p>
            )}
          </div>
        </DropdownMenuLabel>
        <DropdownMenuSeparator />
        <DropdownMenuItem asChild className='cursor-pointer'>
          <Link to={profilePath}>
            <UserCircle className='mr-2 h-4 w-4' />
            <span>{t('auth.profile', { defaultValue: 'Hồ sơ' })}</span>
          </Link>
        </DropdownMenuItem>
        <DropdownMenuItem asChild className='cursor-pointer'>
          <Link to='/orders'>
            <Package className='mr-2 h-4 w-4' />
            <span>{t('nav.orders', { defaultValue: 'Đơn hàng' })}</span>
          </Link>
        </DropdownMenuItem>
        <DropdownMenuItem asChild className='cursor-pointer'>
          <Link to='/wishlist'>
            <Heart className='mr-2 h-4 w-4' />
            <span>{t('nav.wishlist', { defaultValue: 'Yêu thích' })}</span>
          </Link>
        </DropdownMenuItem>
        <DropdownMenuItem asChild className='cursor-pointer'>
          <Link to='/cart'>
            <ShoppingCart className='mr-2 h-4 w-4' />
            <span>{t('nav.cart', { defaultValue: 'Giỏ hàng' })}</span>
          </Link>
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem onClick={handleLogout} className='cursor-pointer'>
          <LogOut className='mr-2 h-4 w-4' />
          <span>{t('auth.logout', { defaultValue: 'Đăng xuất' })}</span>
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

messages.message:
Error: Calling setState synchronously within an effect can trigger cascading renders

Effects are intended to synchronize state between React and external systems such as manually updating the DOM, state management libraries, or other platform APIs. In general, the body of an effect should do one or both of the following:
