import { useEffect, useState } from 'react';
import { Link, useLoaderData, useSearchParams } from 'react-router';
import { useTranslation } from 'react-i18next';

import {
  type AiTargetType,
  useAiParametersListQuery,
  useAiParameterDetailQuery,
  useCreateAiParameterFromDefaultMutation,
  useUpdateAiParameterMutation,
  useActivateAiParameterMutation,
  useCopyAiParameterMutation,
  useDeleteAiParameterMutation,
} from '@/features/ai/parameters';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Textarea } from '@/components/ui/textarea';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';

function targetToLabel(type: AiTargetType) {
  switch (type) {
    case 'SEARCH':
      return 'Search';
    case 'CHAT':
    default:
      return 'Chat';
  }
}

export function AiParametersTab() {
  const { t } = useTranslation();
  const [searchParams] = useSearchParams();
  const loaderData = useLoaderData();
  const currentType = loaderData.type;
  const selectedId = loaderData.selectedId;

  const { data: list } = useAiParametersListQuery(currentType);
  const hasSelection = !!selectedId;
  const { data: selected } = useAiParameterDetailQuery(selectedId ?? '');

  const [description, setDescription] = useState('');
  const [content, setContent] = useState('');

  useEffect(() => {
    if (selected) {
      setDescription(selected.description ?? '');
      setContent(selected.content);
    } else {
      setDescription('');
      setContent('');
    }
  }, [selected]);

  const createFromDefaultMutation = useCreateAiParameterFromDefaultMutation();
  const updateMutation = useUpdateAiParameterMutation();
  const activateMutation = useActivateAiParameterMutation();
  const copyMutation = useCopyAiParameterMutation();
  const deleteMutation = useDeleteAiParameterMutation();

  const isSubmitting =
    createFromDefaultMutation.isPending ||
    updateMutation.isPending ||
    activateMutation.isPending ||
    copyMutation.isPending ||
    deleteMutation.isPending;

  const makeTypeUrl = (type: AiTargetType) => {
    const next = new URLSearchParams(searchParams);
    next.set('type', type);
    next.delete('id');
    return `?${next.toString()}`;
  };

  const makeSelectUrl = (id: string) => {
    const next = new URLSearchParams(searchParams);
    next.set('id', id);
    return `?${next.toString()}`;
  };

  const handleCreateFromDefault = () => {
    createFromDefaultMutation.mutate(currentType);
  };

  const handleUpdate = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!selected) return;
    updateMutation.mutate({
      id: selected.id,
      payload: { content, description },
    });
  };

  const handleActivate = () => {
    if (!selected) return;
    activateMutation.mutate(selected.id);
  };

  const handleCopy = () => {
    if (!selected) return;
    copyMutation.mutate(selected.id);
  };

  const handleDelete = () => {
    if (!selected || selected.active) return;
    deleteMutation.mutate(selected.id);
  };

  return (
    <div className='grid gap-4 lg:grid-cols-[minmax(0,1.4fr)_minmax(0,2fr)]'>
      {/* Left: list + actions */}
      <Card className='h-full'>
        <CardHeader className='flex flex-row items-center justify-between gap-2'>
          <div>
            <CardTitle className='text-base'>
              {t('admin.ai.parameters.title', 'AI Parameters')}
            </CardTitle>
            <p className='text-xs text-muted-foreground'>
              {t(
                'admin.ai.parameters.subtitle',
                'Quản lý các cấu hình YAML cho CHAT và SEARCH.'
              )}
            </p>
          </div>
          <div className='flex items-center gap-2'>
            <Link to={makeTypeUrl('CHAT')}>
              <Button
                size='sm'
                variant={currentType === 'CHAT' ? 'default' : 'outline'}
              >
                {targetToLabel('CHAT')}
              </Button>
            </Link>
            <Link to={makeTypeUrl('SEARCH')}>
              <Button
                size='sm'
                variant={currentType === 'SEARCH' ? 'default' : 'outline'}
              >
                {targetToLabel('SEARCH')}
              </Button>
            </Link>
          </div>
        </CardHeader>
        <CardContent className='space-y-3'>
          <div className='flex items-center justify-between gap-2'>
            <p className='text-xs text-muted-foreground'>
              {t(
                'admin.ai.parameters.count',
                '{{count}} bản ghi cho {{type}}',
                {
                  count: list.length,
                  type: targetToLabel(currentType),
                }
              )}
            </p>
            <Button
              size='sm'
              variant='outline'
              disabled={isSubmitting}
              onClick={handleCreateFromDefault}
            >
              {t(
                'admin.ai.parameters.createFromDefault',
                'Tạo từ default YAML'
              )}
            </Button>
          </div>

          <ScrollArea className='h-[360px]'>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>
                    {t('admin.ai.parameters.table.description', 'Mô tả')}
                  </TableHead>
                  <TableHead>
                    {t('admin.ai.parameters.table.active', 'Trạng thái')}
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {list.map((p) => {
                  const isActive = p.active;
                  const isSelected = selectedId === p.id;
                  return (
                    <TableRow
                      key={p.id}
                      className={`cursor-pointer ${isSelected ? 'bg-muted' : ''}`}
                    >
                      <TableCell>
                        <Link
                          to={makeSelectUrl(p.id)}
                          className='flex flex-col gap-1'
                        >
                          <span className='text-sm font-medium'>
                            {p.description || '(no description)'}
                          </span>
                          <span className='text-xs text-muted-foreground'>
                            {p.id}
                          </span>
                        </Link>
                      </TableCell>
                      <TableCell>
                        <Badge
                          variant={isActive ? 'default' : 'outline'}
                          className='text-xs'
                        >
                          {isActive
                            ? t('admin.ai.parameters.active', 'Đang dùng')
                            : t('admin.ai.parameters.inactive', 'Nháp')}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </ScrollArea>
        </CardContent>
      </Card>

      {/* Right: editor */}
      <Card className='h-full'>
        <CardHeader>
          <CardTitle className='text-base'>
            {hasSelection
              ? t('admin.ai.parameters.editorTitle', 'Chỉnh sửa parameter')
              : t(
                  'admin.ai.parameters.editorEmptyTitle',
                  'Chọn hoặc tạo parameter'
                )}
          </CardTitle>
        </CardHeader>
        <CardContent className='space-y-3'>
          {!hasSelection || !selected ? (
            <p className='text-sm text-muted-foreground'>
              {t(
                'admin.ai.parameters.editorEmpty',
                'Chọn một bản ghi ở bên trái hoặc tạo mới từ default YAML.'
              )}
            </p>
          ) : (
            <form className='space-y-3' onSubmit={handleUpdate}>
              <div className='space-y-1'>
                <label className='text-xs font-medium text-muted-foreground'>
                  {t('admin.ai.parameters.fields.description', 'Mô tả')}
                </label>
                <Input
                  name='description'
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder={t(
                    'admin.ai.parameters.fields.descriptionPlaceholder',
                    'VD: Prompt cho Chat / Search'
                  )}
                />
              </div>

              <div className='space-y-1'>
                <label className='text-xs font-medium text-muted-foreground'>
                  {t('admin.ai.parameters.fields.content', 'Nội dung YAML')}
                </label>
                <Textarea
                  name='content'
                  value={content}
                  onChange={(e) => setContent(e.target.value)}
                  className='font-mono text-xs leading-relaxed'
                  rows={18}
                />
              </div>

              <div className='flex flex-wrap items-center justify-between gap-2 pt-1'>
                <div className='flex gap-2'>
                  <Button type='submit' size='sm' disabled={isSubmitting}>
                    {t('common.save', 'Lưu')}
                  </Button>
                  <Button
                    type='button'
                    variant='outline'
                    size='sm'
                    disabled={isSubmitting || selected.active}
                    onClick={handleActivate}
                  >
                    {t('admin.ai.parameters.actions.activate', 'Kích hoạt')}
                  </Button>
                  <Button
                    type='button'
                    variant='outline'
                    size='sm'
                    disabled={isSubmitting}
                    onClick={handleCopy}
                  >
                    {t('admin.ai.parameters.actions.copy', 'Nhân bản')}
                  </Button>
                </div>
                <Button
                  type='button'
                  variant='destructive'
                  size='sm'
                  disabled={isSubmitting || selected.active}
                  onClick={handleDelete}
                >
                  {t('common.delete', 'Xóa')}
                </Button>
              </div>
            </form>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { IconPlus, IconSearch } from '@tabler/icons-react';
import { toast } from 'sonner';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';

import {
  CategoryTable,
  CategoryStatsCards,
  CategoryFormDialog,
  type Category,
} from '@/features/admin/categories';

import {
  getCategories,
  createCategory,
  updateCategory,
  deleteCategory,
} from '@/features/admin/categories/api';
import { getErrorMessage, isNoResponseError } from '@/features/apiClient';

export default function AdminCategoriesPage() {
  const { t } = useTranslation();
  const [categories, setCategories] = useState<Category[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(
    null
  );
  const [isCreating, setIsCreating] = useState(false);

  // Form state
  const [formData, setFormData] = useState({
    name: '',
    description: '',
  });

  const fetchCategories = useCallback(async () => {
    setLoading(true);
    try {
      const data = await getCategories();
      setCategories(data);
    } catch (error) {
      setCategories([]);
      if (!isNoResponseError(error)) {
        toast.error(
          t('admin.categories.fetchError', 'Không thể tải danh sách')
        );
      }
    } finally {
      setLoading(false);
    }
  }, [t]);

  useEffect(() => {
    void fetchCategories();
  }, [fetchCategories]);

  // Filter categories
  const filteredCategories = categories.filter((category) =>
    category.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const stats = {
    total: categories.length,
    root: categories.filter((c) => !c.parentCategory).length,
    totalProducts: categories.reduce((sum, c) => sum + c.productCount, 0),
  };

  const handleCreate = () => {
    setIsCreating(true);
    setFormData({
      name: '',
      description: '',
    });
    setEditDialogOpen(true);
  };

  const handleEdit = (category: Category) => {
    setIsCreating(false);
    setSelectedCategory(category);
    setFormData({
      name: category.name,
      description: category.description,
    });
    setEditDialogOpen(true);
  };

  const handleDelete = (category: Category) => {
    setSelectedCategory(category);
    setDeleteDialogOpen(true);
  };

  const confirmDelete = async () => {
    if (!selectedCategory) return;
    setDeleting(true);
    try {
      await deleteCategory(selectedCategory.id);
      setCategories((prev) => prev.filter((c) => c.id !== selectedCategory.id));
      toast.success(t('admin.categories.deleteSuccess', 'Đã xóa danh mục'));
      setDeleteDialogOpen(false);
      setSelectedCategory(null);
    } catch (error) {
      if (!isNoResponseError(error)) {
        toast.error(getErrorMessage(error));
      }
    } finally {
      setDeleting(false);
    }
  };

  const handleSave = async () => {
    if (!formData.name.trim() || !formData.description.trim()) {
      toast.error(
        t('admin.categories.fillRequired', 'Vui lòng điền đầy đủ thông tin')
      );
      return;
    }
    setSaving(true);
    try {
      if (isCreating) {
        const created = await createCategory(formData);
        // Update local state to avoid refetch/reload the table
        setCategories((prev) => [created, ...prev]);
        toast.success(t('admin.categories.createSuccess', 'Đã tạo danh mục'));
      } else if (selectedCategory) {
        const updated = await updateCategory(selectedCategory.id, formData);
        setCategories((prev) =>
          prev.map((c) => (c.id === updated.id ? updated : c))
        );
        toast.success(
          t('admin.categories.updateSuccess', 'Đã cập nhật danh mục')
        );
      }
      setEditDialogOpen(false);
    } catch (error) {
      if (!isNoResponseError(error)) {
        toast.error(getErrorMessage(error));
      }
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className='flex flex-col gap-4 py-4'>
      {/* Header */}
      <div className='flex items-center justify-between px-4 lg:px-6'>
        <div>
          <h1 className='text-2xl font-bold'>{t('admin.categories.title')}</h1>
          <p className='text-muted-foreground'>
            {t('admin.categories.subtitle', {
              count: filteredCategories.length,
            })}
          </p>
        </div>
        <Button onClick={handleCreate}>
          <IconPlus className='mr-2 h-4 w-4' />
          {t('admin.categories.addCategory')}
        </Button>
      </div>

      {/* Stats */}
      <div className='px-4 lg:px-6'>
        <CategoryStatsCards {...stats} />
      </div>

      {/* Search */}
      <div className='flex items-center gap-4 px-4 lg:px-6'>
        <div className='relative flex-1 max-w-sm'>
          <IconSearch className='absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground' />
          <Input
            placeholder={t('admin.categories.searchPlaceholder')}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className='pl-10'
          />
        </div>
      </div>

      {/* Table */}
      <div className='px-4 lg:px-6'>
        {loading ? (
          <div className='rounded-lg border p-8 text-center text-muted-foreground'>
            {t('common.loading', 'Đang tải...')}
          </div>
        ) : (
          <CategoryTable
            categories={filteredCategories}
            onEdit={handleEdit}
            onDelete={handleDelete}
          />
        )}
      </div>

      {/* Edit/Create Dialog */}
      <CategoryFormDialog
        open={editDialogOpen}
        onOpenChange={setEditDialogOpen}
        isCreating={isCreating}
        formData={formData}
        onFormChange={setFormData}
        onSave={handleSave}
        saving={saving}
      />

      {/* Delete Dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {t('admin.categories.deleteDialog.title')}
            </DialogTitle>
            <DialogDescription>
              {t('admin.categories.deleteDialog.description', {
                name: selectedCategory?.name,
              })}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant='outline'
              onClick={() => setDeleteDialogOpen(false)}
            >
              {t('common.cancel')}
            </Button>
            <Button
              variant='destructive'
              onClick={() => void confirmDelete()}
              disabled={deleting}
            >
              {deleting
                ? t('common.loading', 'Đang xóa...')
                : t('common.delete')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { IconSearch } from '@tabler/icons-react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

import { useQueryOrders } from '@/features/admin/orders';
import type { OrderResponse, OrderStatus } from '@/features/admin/orders';
import {
  OrderTable,
  OrderStatsCards,
  OrderDetailDialog,
} from '@/features/admin/orders/components';

import { statusOptions } from './data';

const DEFAULT_PAGE = 0;
const DEFAULT_SIZE = 10;
const PAGE_SIZE_OPTIONS = [5, 10, 20, 50];

export default function AdminOrdersPage() {
  const { t } = useTranslation();
  const [searchInput, setSearchInput] = useState('');
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [detailDialogOpen, setDetailDialogOpen] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<OrderResponse | null>(
    null
  );

  const [params, setParams] = useState({
    page: DEFAULT_PAGE,
    size: DEFAULT_SIZE,
    nameSearch: '' as string | undefined,
    orderStatus: undefined as OrderStatus | undefined,
  });

  const { data, isPending } = useQueryOrders(params);
  const orders = data?.content ?? [];
  const totalElements = data?.totalElements ?? 0;
  const totalPages = data?.totalPages ?? 1;

  const stats = useMemo(() => {
    return {
      newOrders: orders.filter((o) => o.orderStatus === 'PAID').length,
      processing: orders.filter((o) => o.orderStatus === 'CONFIRMED').length,
      shipped: orders.filter((o) => o.orderStatus === 'SHIPPED').length,
      revenue: orders
        .filter((o) => o.orderStatus === 'DELIVERED')
        .reduce((sum, o) => sum + o.totalAmount, 0),
    };
  }, [orders]);

  const handleSearch = () => {
    setParams((prev) => ({
      ...prev,
      page: DEFAULT_PAGE,
      nameSearch: searchInput.trim() || undefined,
      orderStatus:
        statusFilter === 'all' ? undefined : (statusFilter as OrderStatus),
    }));
  };

  const handleViewDetails = (order: OrderResponse) => {
    setSelectedOrder(order);
    setDetailDialogOpen(true);
  };

  const handlePageChange = (page: number) => {
    setParams((prev) => ({ ...prev, page }));
  };

  const handlePageSizeChange = (size: number) => {
    setParams((prev) => ({ ...prev, size, page: 0 }));
  };

  return (
    <div className='flex flex-col gap-4 py-4'>
      <div className='flex items-center justify-between px-4 lg:px-6'>
        <div>
          <h1 className='text-2xl font-bold'>{t('admin.orders.title')}</h1>
          <p className='text-muted-foreground'>
            {t('admin.orders.subtitle', { count: totalElements })}
          </p>
        </div>
      </div>

      <div className='px-4 lg:px-6'>
        <OrderStatsCards {...stats} />
      </div>

      <div className='flex flex-wrap items-center gap-4 px-4 lg:px-6'>
        <div className='relative flex-1 min-w-[200px]'>
          <IconSearch className='absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground' />
          <Input
            placeholder={t('admin.orders.searchPlaceholder')}
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
            className='pl-10'
          />
        </div>
        <Select
          value={statusFilter ?? undefined}
          onValueChange={setStatusFilter}
        >
          <SelectTrigger className='w-[180px]'>
            <SelectValue placeholder={t('admin.orders.filterStatus')} />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value='all'>{t('admin.orders.allStatuses')}</SelectItem>
            {statusOptions.map((option) => (
              <SelectItem key={option.value} value={option.value}>
                {option.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button onClick={handleSearch}>
          <IconSearch className='mr-2 h-4 w-4' />
          {t('admin.orders.search', 'Search')}
        </Button>
      </div>

      <div className='px-4 lg:px-6'>
        {isPending ? (
          <p className='text-muted-foreground'>
            {t('common.loading', 'Loading...')}
          </p>
        ) : (
          <OrderTable
            orders={orders}
            onViewDetails={handleViewDetails}
            pagination={{
              page: params.page,
              totalPages,
              onPageChange: handlePageChange,
              pageSize: params.size,
              pageSizeOptions: PAGE_SIZE_OPTIONS,
              onPageSizeChange: handlePageSizeChange,
            }}
          />
        )}
      </div>

      <OrderDetailDialog
        open={detailDialogOpen}
        onOpenChange={setDetailDialogOpen}
        order={selectedOrder}
      />
    </div>
  );
}

import { useRef, useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router';
import { IconTrash, IconX, IconPlus } from '@tabler/icons-react';
import { toast } from 'sonner';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  genderOptions,
  statusOptions,
  type Gender,
  type ProductStatus as ShoeStatus,
} from './data';
import { useBrands, useCategories } from '@/features/products';
import { useCreateShoeMutation } from '@/features/admin/products';

interface VariantFormState {
  id: string;
  size: string;
  color: string;
  stockQuantity: string;
  images: File[];
  previewUrls: string[];
}

interface ShoeFormState {
  name: string;
  brandId: string;
  categoryId: string;
  gender: Gender;
  status: ShoeStatus;
  basePrice: string;
  material: string;
  description: string;
}

export default function AddShoePage() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { data: brands = [] } = useBrands();
  const { data: categories = [] } = useCategories();

  const [shoe, setShoe] = useState<ShoeFormState>({
    name: '',
    brandId: '',
    categoryId: '',
    gender: 'UNISEX',
    status: 'ACTIVE',
    basePrice: '',
    material: '',
    description: '',
  });

  const [variants, setVariants] = useState<VariantFormState[]>([
    createEmptyVariant(1),
  ]);
  const createShoeMutation = useCreateShoeMutation();

  const [shoeImages, setShoeImages] = useState<File[]>([]);
  const [shoePreviewUrls, setShoePreviewUrls] = useState<string[]>([]);
  const mainImageInputRef = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    return () => {
      shoePreviewUrls.forEach((url) => URL.revokeObjectURL(url));
      variants.forEach((v) =>
        v.previewUrls.forEach((url) => URL.revokeObjectURL(url))
      );
    };
  }, []);

  const handleChooseMainImage = () => {
    mainImageInputRef.current?.click();
  };

  const handleMainImageChange = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const files = Array.from(event.target.files || []);
    if (files.length === 0) return;

    const newPreviewUrls = files.map((file) => URL.createObjectURL(file));
    setShoeImages((prev) => [...prev, ...files]);
    setShoePreviewUrls((prev) => [...prev, ...newPreviewUrls]);

    if (mainImageInputRef.current) mainImageInputRef.current.value = '';
  };

  const removeShoeImage = (index: number) => {
    URL.revokeObjectURL(shoePreviewUrls[index]);
    setShoeImages((prev) => prev.filter((_, i) => i !== index));
    setShoePreviewUrls((prev) => prev.filter((_, i) => i !== index));
  };

  const handleVariantImageChange = (
    variantId: string,
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const files = Array.from(event.target.files || []);
    if (files.length === 0) return;

    const newPreviewUrls = files.map((file) => URL.createObjectURL(file));

    setVariants((prev) =>
      prev.map((v) =>
        v.id === variantId
          ? {
              ...v,
              images: [...v.images, ...files],
              previewUrls: [...v.previewUrls, ...newPreviewUrls],
            }
          : v
      )
    );

    event.target.value = '';
  };

  const removeVariantImage = (variantId: string, imageIndex: number) => {
    setVariants((prev) =>
      prev.map((v) => {
        if (v.id === variantId) {
          URL.revokeObjectURL(v.previewUrls[imageIndex]);
          return {
            ...v,
            images: v.images.filter((_, i) => i !== imageIndex),
            previewUrls: v.previewUrls.filter((_, i) => i !== imageIndex),
          };
        }
        return v;
      })
    );
  };

  const handleChange =
    (field: keyof ShoeFormState) =>
    (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      const value = event.target.value;

      setShoe((prev) => ({
        ...prev,
        [field]: value,
      }));
    };

  const handleSelectChange =
    (field: keyof ShoeFormState) => (value: string) => {
      setShoe((prev) => ({
        ...prev,
        [field]: value,
      }));
    };

  const handleVariantChange =
    (id: string, field: keyof VariantFormState) =>
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const value = event.target.value;
      setVariants((prev) =>
        prev.map((variant) =>
          variant.id === id ? { ...variant, [field]: value } : variant
        )
      );
    };

  const handleAddVariant = () => {
    setVariants((prev) => [...prev, createEmptyVariant(prev.length + 1)]);
  };

  const handleRemoveVariant = (id: string) => {
    setVariants((prev) => {
      const variant = prev.find((v) => v.id === id);
      variant?.previewUrls.forEach((url) => URL.revokeObjectURL(url));
      return prev.length > 1 ? prev.filter((v) => v.id !== id) : prev;
    });
  };

  const totalStock = variants.reduce(
    (sum, v) => sum + (Number(v.stockQuantity) || 0),
    0
  );

  const handleCancel = () => {
    navigate('/admin/products');
  };

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();

    if (isSubmitting) return;

    if (!shoe.name || !shoe.brandId || !shoe.categoryId || !shoe.basePrice) {
      toast.error('Vui lòng điền đầy đủ các trường bắt buộc');
      return;
    }

    setIsSubmitting(true);
    try {
      const payload = {
        name: shoe.name,
        description: shoe.description,
        material: shoe.material,
        gender: shoe.gender,
        status: shoe.status,
        categoryId: shoe.categoryId,
        brandId: shoe.brandId,
        price: Number(shoe.basePrice) || 0,
        variants: variants.map((v) => ({
          size: v.size,
          color: v.color,
          quantity: Number(v.stockQuantity) || 0,
        })),
      };

      const variantImagesArray = variants.map((v) => v.images);

      await createShoeMutation.mutateAsync({
        payload,
        shoeImages,
        variantImages: variantImagesArray,
      });
      toast.success('Tạo sản phẩm thành công!');
      navigate('/admin/products');
    } catch (error) {
      console.error('Failed to create shoe:', error);
      toast.error('Có lỗi xảy ra khi tạo sản phẩm');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className='flex flex-col gap-6 px-4 py-4 lg:px-6'>
      <div>
        <p className='text-sm font-medium text-muted-foreground'>
          {t('admin.products.addPage.breadcrumb')}
        </p>
        <h1 className='mt-1 text-2xl font-bold'>
          {t('admin.products.addPage.title')}
        </h1>
        <p className='text-sm text-muted-foreground'>
          {t('admin.products.addPage.subtitle')}
        </p>
      </div>

      <form onSubmit={handleSubmit} className='flex flex-col gap-6'>
        <div className='space-y-6'>
          <Card>
            <CardHeader>
              <CardTitle>
                {t('admin.products.addPage.sections.generalInfo')}
              </CardTitle>
            </CardHeader>
            <CardContent className='space-y-4'>
              <div className='space-y-2'>
                <Label htmlFor='name'>
                  {t('admin.products.addPage.fields.name.label')}
                </Label>
                <Input
                  id='name'
                  value={shoe.name}
                  onChange={handleChange('name')}
                  placeholder={t(
                    'admin.products.addPage.fields.name.placeholder'
                  )}
                />
              </div>

              <div className='grid gap-4 md:grid-cols-2'>
                <div className='space-y-2'>
                  <Label>
                    {t('admin.products.addPage.fields.brand.label')}
                  </Label>
                  <Select
                    value={shoe.brandId}
                    onValueChange={handleSelectChange('brandId')}
                  >
                    <SelectTrigger className='w-full'>
                      <SelectValue
                        placeholder={t(
                          'admin.products.addPage.fields.brand.placeholder'
                        )}
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {brands.map((b) => (
                        <SelectItem key={b.id} value={b.id}>
                          {b.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className='space-y-2'>
                  <Label>
                    {t('admin.products.addPage.fields.gender.label')}
                  </Label>
                  <Select
                    value={shoe.gender}
                    onValueChange={handleSelectChange('gender')}
                  >
                    <SelectTrigger className='w-full'>
                      <SelectValue
                        placeholder={t(
                          'admin.products.addPage.fields.gender.placeholder'
                        )}
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {genderOptions.map((option) => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className='grid gap-4 md:grid-cols-2'>
                <div className='space-y-2'>
                  <Label>
                    {t('admin.products.addPage.fields.category.label')}
                  </Label>
                  <Select
                    value={shoe.categoryId}
                    onValueChange={handleSelectChange('categoryId')}
                  >
                    <SelectTrigger className='w-full'>
                      <SelectValue
                        placeholder={t(
                          'admin.products.addPage.fields.category.placeholder'
                        )}
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {categories.map((c) => (
                        <SelectItem key={c.id} value={c.id}>
                          {c.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className='space-y-2'>
                  <Label>
                    {t('admin.products.addPage.fields.status.label')}
                  </Label>
                  <Select
                    value={shoe.status}
                    onValueChange={handleSelectChange('status')}
                  >
                    <SelectTrigger className='w-full'>
                      <SelectValue
                        placeholder={t(
                          'admin.products.addPage.fields.status.placeholder'
                        )}
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {statusOptions.map((option) => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className='grid gap-4 md:grid-cols-2'>
                <div className='space-y-2'>
                  <Label htmlFor='basePrice'>
                    {t('admin.products.addPage.fields.basePrice.label')}
                  </Label>
                  <Input
                    id='basePrice'
                    type='number'
                    min={0}
                    value={shoe.basePrice}
                    onChange={handleChange('basePrice')}
                    placeholder={t(
                      'admin.products.addPage.fields.basePrice.placeholder'
                    )}
                  />
                </div>

                <div className='space-y-2'>
                  <Label>
                    {t('admin.products.addPage.fields.totalStock.label')}
                  </Label>
                  <Input value={totalStock} readOnly />
                </div>
              </div>

              <div className='space-y-2'>
                <Label htmlFor='material'>
                  {t('admin.products.addPage.fields.material.label')}
                </Label>
                <Input
                  id='material'
                  value={shoe.material}
                  onChange={handleChange('material')}
                  placeholder={t(
                    'admin.products.addPage.fields.material.placeholder'
                  )}
                />
              </div>

              <div className='space-y-2'>
                <Label htmlFor='description'>
                  {t('admin.products.addPage.fields.description.label')}
                </Label>
                <Textarea
                  id='description'
                  value={shoe.description}
                  onChange={handleChange('description')}
                  placeholder={t(
                    'admin.products.addPage.fields.description.placeholder'
                  )}
                  rows={4}
                />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>
                {t('admin.products.addPage.sections.images')}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <input
                ref={mainImageInputRef}
                type='file'
                accept='image/*'
                multiple
                className='hidden'
                onChange={handleMainImageChange}
              />

              <div className='grid grid-cols-2 gap-4 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 mb-4'>
                {shoePreviewUrls.map((url, index) => (
                  <div
                    key={url}
                    className='group relative aspect-square overflow-hidden rounded-lg border bg-muted'
                  >
                    <img
                      src={url}
                      alt={`Shoe ${index}`}
                      className='h-full w-full object-cover'
                    />
                    <button
                      type='button'
                      onClick={() => removeShoeImage(index)}
                      className='absolute right-1 top-1 flex h-6 w-6 items-center justify-center rounded-full bg-destructive text-white opacity-0 transition-opacity group-hover:opacity-100'
                    >
                      <IconX size={14} />
                    </button>
                  </div>
                ))}

                <button
                  type='button'
                  onClick={handleChooseMainImage}
                  className='flex aspect-square flex-col items-center justify-center gap-2 rounded-lg border border-dashed bg-muted/40 transition-colors hover:bg-muted/60'
                >
                  <IconPlus className='h-6 w-6 text-muted-foreground' />
                  <span className='text-xs font-medium text-muted-foreground'>
                    Thêm ảnh
                  </span>
                </button>
              </div>

              <div className='text-center'>
                <p className='text-xs text-muted-foreground'>
                  {t('admin.products.addPage.imageDropzone.hint')}
                </p>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className='flex flex-row items-center justify-between'>
              <div>
                <CardTitle>
                  {t('admin.products.addPage.sections.variants')}
                </CardTitle>
                <p className='mt-1 text-xs text-muted-foreground'>
                  {t('admin.products.addPage.variants.subtitle')}
                </p>
              </div>
              <Button size='sm' type='button' onClick={handleAddVariant}>
                {t('admin.products.addPage.variants.addButton')}
              </Button>
            </CardHeader>
            <CardContent className='space-y-6'>
              {variants.map((variant, index) => (
                <div
                  key={variant.id}
                  className='rounded-lg border bg-card p-4 shadow-sm'
                >
                  <div className='mb-3 flex items-center justify-between'>
                    <p className='text-sm font-semibold'>
                      {t('admin.products.addPage.variants.itemTitle', {
                        index: index + 1,
                      })}
                    </p>
                    <Button
                      type='button'
                      variant='ghost'
                      size='sm'
                      className='text-destructive hover:text-destructive'
                      onClick={() => handleRemoveVariant(variant.id)}
                      disabled={variants.length === 1}
                    >
                      <IconTrash className='mr-2 h-4 w-4' />
                      {t('common.delete')}
                    </Button>
                  </div>

                  <div className='grid gap-4 md:grid-cols-2'>
                    <div className='space-y-2'>
                      <Label htmlFor={`size-${variant.id}`}>
                        {t('admin.products.addPage.variants.fields.size.label')}
                      </Label>
                      <Input
                        id={`size-${variant.id}`}
                        value={variant.size}
                        onChange={handleVariantChange(variant.id, 'size')}
                        placeholder={t(
                          'admin.products.addPage.variants.fields.size.placeholder'
                        )}
                      />
                    </div>
                    <div className='space-y-2'>
                      <Label htmlFor={`color-${variant.id}`}>
                        {t(
                          'admin.products.addPage.variants.fields.color.label'
                        )}
                      </Label>
                      <Input
                        id={`color-${variant.id}`}
                        value={variant.color}
                        onChange={handleVariantChange(variant.id, 'color')}
                        placeholder={t(
                          'admin.products.addPage.variants.fields.color.placeholder'
                        )}
                      />
                    </div>
                  </div>

                  <div className='grid gap-4 md:grid-cols-2 mt-4'>
                    <div className='space-y-2'>
                      <Label htmlFor={`stock-${variant.id}`}>
                        {t(
                          'admin.products.addPage.variants.fields.stock.label'
                        )}
                      </Label>
                      <Input
                        id={`stock-${variant.id}`}
                        type='number'
                        min={0}
                        value={variant.stockQuantity}
                        onChange={handleVariantChange(
                          variant.id,
                          'stockQuantity'
                        )}
                        placeholder={t(
                          'admin.products.addPage.variants.fields.stock.placeholder'
                        )}
                      />
                    </div>
                  </div>

                  <div className='mt-4 space-y-2'>
                    <Label>
                      {t('admin.products.addPage.variants.image.label')}
                    </Label>
                    <div className='grid grid-cols-3 gap-2 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6'>
                      {variant.previewUrls.map((url, imgIndex) => (
                        <div
                          key={url}
                          className='group relative aspect-square overflow-hidden rounded-md border bg-muted'
                        >
                          <img
                            src={url}
                            alt={`Variant ${index} - ${imgIndex}`}
                            className='h-full w-full object-cover'
                          />
                          <button
                            type='button'
                            onClick={() =>
                              removeVariantImage(variant.id, imgIndex)
                            }
                            className='absolute right-0.5 top-0.5 flex h-5 w-5 items-center justify-center rounded-full bg-destructive text-white opacity-0 transition-opacity group-hover:opacity-100'
                          >
                            <IconX size={12} />
                          </button>
                        </div>
                      ))}

                      <label className='flex aspect-square cursor-pointer flex-col items-center justify-center gap-1 rounded-md border border-dashed bg-muted/40 transition-colors hover:bg-muted/60'>
                        <IconPlus className='h-4 w-4 text-muted-foreground' />
                        <span className='text-[10px] font-medium text-muted-foreground'>
                          Ảnh
                        </span>
                        <input
                          type='file'
                          accept='image/*'
                          multiple
                          className='hidden'
                          onChange={(e) =>
                            handleVariantImageChange(variant.id, e)
                          }
                        />
                      </label>
                    </div>
                  </div>
                </div>
              ))}
            </CardContent>
          </Card>
        </div>
      </form>

      <div className='sticky bottom-0 z-40 border-t bg-background/90 px-0 py-3 backdrop-blur'>
        <div className='flex items-center justify-end gap-2'>
          <Button variant='outline' onClick={handleCancel}>
            {t('common.cancel')}
          </Button>
          <Button onClick={handleSubmit}>{t('common.save')}</Button>
        </div>
      </div>
    </div>
  );
}

function createEmptyVariant(index: number): VariantFormState {
  return {
    id: `variant-${index}-${Date.now()}`,
    size: '',
    color: '',
    stockQuantity: '',
    images: [],
    previewUrls: [],
  };
}

import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import { useLocation, useNavigate, useParams } from 'react-router';
import {
  DndContext,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors,
  type DragEndEvent,
} from '@dnd-kit/core';
import {
  SortableContext,
  rectSortingStrategy,
  useSortable,
  arrayMove,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { IconTrash, IconX, IconPlus } from '@tabler/icons-react';
import { toast } from 'sonner';

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  genderOptions,
  statusOptions,
  type Gender,
  type ProductStatus as ShoeStatus,
} from './data';
import { useBrands, useCategories, useShoeById } from '@/features/products';
import { useUpdateShoeMutation } from '@/features/admin/products';

interface VariantFormState {
  id: string;
  size: string;
  color: string;
  stockQuantity: string;
  existingImageUrls: string[];
  keepImageUrls: string[];
  newImages: File[];
  newPreviewUrls: string[];
}

interface ShoeFormState {
  name: string;
  brandId: string;
  categoryId: string;
  gender: Gender;
  status: ShoeStatus;
  basePrice: string;
  material: string;
  description: string;
}

function SortableImageItem({
  id,
  children,
}: {
  id: string;
  children: ReactNode;
}) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={isDragging ? 'z-10 opacity-80' : ''}
      {...attributes}
      {...listeners}
    >
      <div className='relative'>{children}</div>
    </div>
  );
}

export default function EditShoePage() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();
  const { id } = useParams<{ id: string }>();
  const backTo = (location.state as { from?: string } | null)?.from;

  const { data: brands = [] } = useBrands();
  const { data: categories = [] } = useCategories();
  const { data: shoeData, isLoading, isError } = useShoeById(id);

  const [shoe, setShoe] = useState<ShoeFormState | null>(null);
  const [variants, setVariants] = useState<VariantFormState[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [shoeExistingImageUrls, setShoeExistingImageUrls] = useState<string[]>(
    []
  );
  const [shoeKeepImageUrls, setShoeKeepImageUrls] = useState<string[]>([]);
  const [shoeNewImages, setShoeNewImages] = useState<File[]>([]);
  const [shoeNewPreviewUrls, setShoeNewPreviewUrls] = useState<string[]>([]);
  const mainImageInputRef = useRef<HTMLInputElement | null>(null);

  const updateShoeMutation = useUpdateShoeMutation();

  useEffect(() => {
    if (!shoeData) return;

    setShoe({
      name: shoeData.name,
      brandId: shoeData.brandId,
      categoryId: shoeData.categoryId,
      gender: shoeData.gender as Gender,
      status: shoeData.status as ShoeStatus,
      basePrice: String(shoeData.price),
      material: shoeData.material,
      description: shoeData.description,
    });

    setShoeExistingImageUrls(shoeData.imageUrls ?? []);
    setShoeKeepImageUrls(shoeData.imageUrls ?? []);

    setVariants(
      shoeData.variants.map((v) => ({
        id: v.id,
        size: v.size,
        color: v.color,
        stockQuantity: String(v.quantity),
        existingImageUrls: v.imageUrls ?? [],
        keepImageUrls: v.imageUrls ?? [],
        newImages: [],
        newPreviewUrls: [],
      }))
    );
  }, [shoeData]);

  useEffect(() => {
    return () => {
      shoeNewPreviewUrls.forEach((url) => URL.revokeObjectURL(url));
      variants.forEach((v) =>
        v.newPreviewUrls.forEach((url) => URL.revokeObjectURL(url))
      );
    };
  }, [shoeNewPreviewUrls, variants]);

  const totalStock = useMemo(
    () => variants.reduce((sum, v) => sum + (Number(v.stockQuantity) || 0), 0),
    [variants]
  );

  const handleChange =
    (field: keyof ShoeFormState) =>
    (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      const value = event.target.value;

      setShoe((prev) =>
        prev
          ? {
              ...prev,
              [field]: value,
            }
          : prev
      );
    };

  const handleSelectChange =
    (field: keyof ShoeFormState) => (value: string) => {
      setShoe((prev) =>
        prev
          ? {
              ...prev,
              [field]: value,
            }
          : prev
      );
    };

  const handleVariantChange =
    (id: string, field: keyof VariantFormState) =>
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const value = event.target.value;
      setVariants((prev) =>
        prev.map((variant) =>
          variant.id === id ? { ...variant, [field]: value } : variant
        )
      );
    };

  const handleRemoveVariantAt = (index: number) => {
    setVariants((prev) => prev.filter((_, i) => i !== index));
  };

  const handleAddVariant = () => {
    setVariants((prev) => [
      ...prev,
      {
        id: crypto.randomUUID(),
        size: '',
        color: '',
        stockQuantity: '0',
        existingImageUrls: [],
        keepImageUrls: [],
        newImages: [],
        newPreviewUrls: [],
      },
    ]);
  };

  const handleChooseMainImage = () => {
    mainImageInputRef.current?.click();
  };

  const handleMainImageChange = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const files = Array.from(event.target.files || []);
    if (files.length === 0) return;

    const newPreviewUrls = files.map((file) => URL.createObjectURL(file));
    setShoeNewImages((prev) => [...prev, ...files]);
    setShoeNewPreviewUrls((prev) => [...prev, ...newPreviewUrls]);

    if (mainImageInputRef.current) mainImageInputRef.current.value = '';
  };

  const removeNewShoeImage = (index: number) => {
    URL.revokeObjectURL(shoeNewPreviewUrls[index]);
    setShoeNewImages((prev) => prev.filter((_, i) => i !== index));
    setShoeNewPreviewUrls((prev) => prev.filter((_, i) => i !== index));
  };

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 6 },
    })
  );

  const removeExistingShoeImage = (url: string) => {
    setShoeExistingImageUrls((prev) => prev.filter((u) => u !== url));
    setShoeKeepImageUrls((prev) => prev.filter((u) => u !== url));
  };

  const handleShoeImagesDragEnd = ({ active, over }: DragEndEvent) => {
    if (!over || active.id === over.id) return;

    const items = [
      ...shoeExistingImageUrls.map((url) => ({
        id: `existing:${url}`,
        type: 'existing' as const,
        value: url,
      })),
      ...shoeNewPreviewUrls.map((url) => ({
        id: `new:${url}`,
        type: 'new' as const,
        value: url,
      })),
    ];

    const oldIndex = items.findIndex((item) => item.id === String(active.id));
    const newIndex = items.findIndex((item) => item.id === String(over.id));
    if (oldIndex < 0 || newIndex < 0) return;

    const reordered = arrayMove(items, oldIndex, newIndex);
    const reorderedExisting = reordered
      .filter((item) => item.type === 'existing')
      .map((item) => item.value);
    const reorderedNew = reordered
      .filter((item) => item.type === 'new')
      .map((item) => item.value);

    setShoeExistingImageUrls(reorderedExisting);
    setShoeKeepImageUrls((prevKeep) =>
      reorderedExisting.filter((url) => prevKeep.includes(url))
    );

    const newImageByPreview = new Map(
      shoeNewPreviewUrls.map((preview, index) => [
        preview,
        shoeNewImages[index],
      ])
    );
    setShoeNewPreviewUrls(reorderedNew);
    setShoeNewImages(
      reorderedNew
        .map((preview) => newImageByPreview.get(preview))
        .filter((file): file is File => Boolean(file))
    );
  };

  const handleVariantImageChange = (
    variantId: string,
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const files = Array.from(event.target.files || []);
    if (files.length === 0) return;

    const newPreviewUrls = files.map((file) => URL.createObjectURL(file));

    setVariants((prev) =>
      prev.map((v) =>
        v.id === variantId
          ? {
              ...v,
              newImages: [...v.newImages, ...files],
              newPreviewUrls: [...v.newPreviewUrls, ...newPreviewUrls],
            }
          : v
      )
    );

    event.target.value = '';
  };

  const removeVariantNewImageByUrl = (
    variantId: string,
    previewUrl: string
  ) => {
    setVariants((prev) =>
      prev.map((v) => {
        if (v.id !== variantId) return v;

        const imageIndex = v.newPreviewUrls.indexOf(previewUrl);
        if (imageIndex < 0) return v;

        URL.revokeObjectURL(v.newPreviewUrls[imageIndex]);
        return {
          ...v,
          newImages: v.newImages.filter((_, i) => i !== imageIndex),
          newPreviewUrls: v.newPreviewUrls.filter((_, i) => i !== imageIndex),
        };
      })
    );
  };

  const removeVariantExistingImage = (variantId: string, url: string) => {
    setVariants((prev) =>
      prev.map((v) =>
        v.id === variantId
          ? {
              ...v,
              existingImageUrls: v.existingImageUrls.filter((u) => u !== url),
              keepImageUrls: v.keepImageUrls.filter((u) => u !== url),
            }
          : v
      )
    );
  };

  const handleVariantImagesDragEnd =
    (variantId: string) =>
    ({ active, over }: DragEndEvent) => {
      if (!over || active.id === over.id) return;

      setVariants((prev) =>
        prev.map((v) => {
          if (v.id !== variantId) return v;

          const items = [
            ...v.existingImageUrls.map((url) => ({
              id: `existing:${url}`,
              type: 'existing' as const,
              value: url,
            })),
            ...v.newPreviewUrls.map((url) => ({
              id: `new:${url}`,
              type: 'new' as const,
              value: url,
            })),
          ];

          const oldIndex = items.findIndex(
            (item) => item.id === String(active.id)
          );
          const newIndex = items.findIndex(
            (item) => item.id === String(over.id)
          );
          if (oldIndex < 0 || newIndex < 0) return v;

          const reordered = arrayMove(items, oldIndex, newIndex);
          const reorderedExisting = reordered
            .filter((item) => item.type === 'existing')
            .map((item) => item.value);
          const reorderedNew = reordered
            .filter((item) => item.type === 'new')
            .map((item) => item.value);

          const newImageByPreview = new Map(
            v.newPreviewUrls.map((preview, index) => [
              preview,
              v.newImages[index],
            ])
          );

          return {
            ...v,
            existingImageUrls: reorderedExisting,
            keepImageUrls: reorderedExisting.filter((url) =>
              v.keepImageUrls.includes(url)
            ),
            newPreviewUrls: reorderedNew,
            newImages: reorderedNew
              .map((preview) => newImageByPreview.get(preview))
              .filter((file): file is File => Boolean(file)),
          };
        })
      );
    };

  const handleCancel = () => {
    navigate(backTo || '/admin/products');
  };

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();

    if (!shoe || !id || isSubmitting) return;

    if (!shoe.name || !shoe.brandId || !shoe.categoryId || !shoe.basePrice) {
      toast.error('Vui lòng điền đầy đủ các trường bắt buộc');
      return;
    }

    const seenVariants = new Set<string>();
    for (const variant of variants) {
      const sizeKey = variant.size.trim().toLowerCase();
      const colorKey = variant.color.trim().toLowerCase();
      const key = `${sizeKey}|${colorKey}`;

      if (!sizeKey || !colorKey) {
        toast.error('Vui lòng nhập đầy đủ size và màu cho biến thể');
        return;
      }

      if (seenVariants.has(key)) {
        toast.error('Không được trùng size và màu giữa các biến thể');
        return;
      }

      seenVariants.add(key);
    }

    setIsSubmitting(true);
    try {
      const payload = {
        name: shoe.name,
        description: shoe.description,
        material: shoe.material,
        gender: shoe.gender,
        status: shoe.status,
        categoryId: shoe.categoryId,
        brandId: shoe.brandId,
        price: Number(shoe.basePrice) || 0,
        variants: variants.map((v) => ({
          id: v.existingImageUrls.length > 0 ? v.id : undefined,
          size: v.size,
          color: v.color,
          quantity: Number(v.stockQuantity) || 0,
        })),
        keepShoeImageUrls: shoeKeepImageUrls,
        variantImageUpdates: variants
          .filter((v) => v.existingImageUrls.length > 0)
          .map((v) => ({
            variantId: v.id,
            keepImageUrls: v.keepImageUrls,
          })),
      };

      await updateShoeMutation.mutateAsync({
        id,
        payload,
        shoeImages: shoeNewImages,
        variantImages: variants.map((v) => v.newImages),
      });
      toast.success('Cập nhật sản phẩm thành công!');
      navigate(backTo || `/admin/products/${id}`);
    } catch (error) {
      console.error('Failed to update shoe:', error);
      toast.error('Có lỗi xảy ra khi cập nhật sản phẩm');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading || !shoe) {
    return (
      <div className='flex flex-1 items-center justify-center'>
        <p className='text-sm text-muted-foreground'>
          {t('common.loading', 'Đang tải dữ liệu sản phẩm...')}
        </p>
      </div>
    );
  }

  if (isError) {
    return (
      <div className='flex flex-1 flex-col items-center justify-center gap-2'>
        <p className='text-sm text-destructive'>
          {t(
            'admin.products.editPage.loadError',
            'Không thể tải dữ liệu sản phẩm'
          )}
        </p>
        <Button variant='outline' onClick={handleCancel}>
          {t('common.back', 'Quay lại')}
        </Button>
      </div>
    );
  }

  return (
    <div className='flex flex-col gap-6 px-4 py-4 lg:px-6'>
      <div>
        <p className='text-sm font-medium text-muted-foreground'>
          {t('admin.products.editPage.breadcrumb', 'Sản phẩm / Chỉnh sửa')}
        </p>
        <h1 className='mt-1 text-2xl font-bold'>
          {t('admin.products.editPage.title', 'Chỉnh sửa sản phẩm')}
        </h1>
        <p className='text-sm text-muted-foreground'>
          {t(
            'admin.products.editPage.subtitle',
            'Cập nhật thông tin chi tiết cho sản phẩm'
          )}
        </p>
      </div>

      <form onSubmit={handleSubmit} className='flex flex-col gap-6'>
        <div className='space-y-6'>
          <Card>
            <CardHeader>
              <CardTitle>
                {t('admin.products.addPage.sections.generalInfo')}
              </CardTitle>
            </CardHeader>
            <CardContent className='space-y-4'>
              <div className='space-y-2'>
                <Label htmlFor='name'>
                  {t('admin.products.addPage.fields.name.label')}
                </Label>
                <Input
                  id='name'
                  value={shoe.name}
                  onChange={handleChange('name')}
                  placeholder={t(
                    'admin.products.addPage.fields.name.placeholder'
                  )}
                />
              </div>

              <div className='grid gap-4 md:grid-cols-2'>
                <div className='space-y-2'>
                  <Label>
                    {t('admin.products.addPage.fields.brand.label')}
                  </Label>
                  <Select
                    value={shoe.brandId}
                    onValueChange={handleSelectChange('brandId')}
                  >
                    <SelectTrigger className='w-full'>
                      <SelectValue
                        placeholder={t(
                          'admin.products.addPage.fields.brand.placeholder'
                        )}
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {brands.map((b) => (
                        <SelectItem key={b.id} value={b.id}>
                          {b.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className='space-y-2'>
                  <Label>
                    {t('admin.products.addPage.fields.gender.label')}
                  </Label>
                  <Select
                    value={shoe.gender}
                    onValueChange={handleSelectChange('gender')}
                  >
                    <SelectTrigger className='w-full'>
                      <SelectValue
                        placeholder={t(
                          'admin.products.addPage.fields.gender.placeholder'
                        )}
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {genderOptions.map((option) => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className='grid gap-4 md:grid-cols-2'>
                <div className='space-y-2'>
                  <Label>
                    {t('admin.products.addPage.fields.category.label')}
                  </Label>
                  <Select
                    value={shoe.categoryId}
                    onValueChange={handleSelectChange('categoryId')}
                  >
                    <SelectTrigger className='w-full'>
                      <SelectValue
                        placeholder={t(
                          'admin.products.addPage.fields.category.placeholder'
                        )}
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {categories.map((c) => (
                        <SelectItem key={c.id} value={c.id}>
                          {c.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className='space-y-2'>
                  <Label>
                    {t('admin.products.addPage.fields.status.label')}
                  </Label>
                  <Select
                    value={shoe.status}
                    onValueChange={handleSelectChange('status')}
                  >
                    <SelectTrigger className='w-full'>
                      <SelectValue
                        placeholder={t(
                          'admin.products.addPage.fields.status.placeholder'
                        )}
                      />
                    </SelectTrigger>
                    <SelectContent>
                      {statusOptions.map((option) => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className='grid gap-4 md:grid-cols-2'>
                <div className='space-y-2'>
                  <Label htmlFor='basePrice'>
                    {t('admin.products.addPage.fields.basePrice.label')}
                  </Label>
                  <Input
                    id='basePrice'
                    type='number'
                    min={0}
                    value={shoe.basePrice}
                    onChange={handleChange('basePrice')}
                    placeholder={t(
                      'admin.products.addPage.fields.basePrice.placeholder'
                    )}
                  />
                </div>

                <div className='space-y-2'>
                  <Label>
                    {t('admin.products.addPage.fields.totalStock.label')}
                  </Label>
                  <Input value={totalStock} readOnly />
                </div>
              </div>

              <div className='space-y-2'>
                <Label htmlFor='material'>
                  {t('admin.products.addPage.fields.material.label')}
                </Label>
                <Input
                  id='material'
                  value={shoe.material}
                  onChange={handleChange('material')}
                  placeholder={t(
                    'admin.products.addPage.fields.material.placeholder'
                  )}
                />
              </div>

              <div className='space-y-2'>
                <Label htmlFor='description'>
                  {t('admin.products.addPage.fields.description.label')}
                </Label>
                <Textarea
                  id='description'
                  value={shoe.description}
                  onChange={handleChange('description')}
                  placeholder={t(
                    'admin.products.addPage.fields.description.placeholder'
                  )}
                  rows={4}
                />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>
                {t('admin.products.addPage.sections.images')}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <input
                ref={mainImageInputRef}
                type='file'
                accept='image/*'
                multiple
                className='hidden'
                onChange={handleMainImageChange}
              />

              <DndContext
                sensors={sensors}
                collisionDetection={closestCenter}
                onDragEnd={handleShoeImagesDragEnd}
              >
                <SortableContext
                  items={[
                    ...shoeExistingImageUrls.map((url) => `existing:${url}`),
                    ...shoeNewPreviewUrls.map((url) => `new:${url}`),
                  ]}
                  strategy={rectSortingStrategy}
                >
                  <div className='grid grid-cols-2 gap-4 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5'>
                    {shoeExistingImageUrls.map((url, index) => {
                      const isPrimary = index === 0;

                      return (
                        <SortableImageItem
                          key={`existing:${url}`}
                          id={`existing:${url}`}
                        >
                          <div className='group relative aspect-square overflow-hidden rounded-lg border border-primary bg-muted'>
                            <img
                              src={url}
                              alt='Shoe existing'
                              className='h-full w-full object-cover'
                            />

                            {isPrimary && (
                              <span className='absolute left-1 top-1 rounded bg-primary px-2 py-0.5 text-[10px] font-semibold text-primary-foreground'>
                                Ảnh chính
                              </span>
                            )}

                            <button
                              type='button'
                              onClick={() => removeExistingShoeImage(url)}
                              className='absolute right-1 top-1 z-20 flex h-6 w-6 items-center justify-center rounded bg-destructive text-white'
                            >
                              <IconX size={14} />
                            </button>
                          </div>
                        </SortableImageItem>
                      );
                    })}

                    {shoeNewPreviewUrls.map((url) => {
                      const mergedIndex =
                        shoeExistingImageUrls.length +
                        shoeNewPreviewUrls.indexOf(url);
                      const isPrimary = mergedIndex === 0;

                      return (
                        <SortableImageItem key={`new:${url}`} id={`new:${url}`}>
                          <div className='group relative aspect-square overflow-hidden rounded-lg border bg-muted'>
                            <img
                              src={url}
                              alt='Shoe new'
                              className='h-full w-full object-cover'
                            />

                            {isPrimary && (
                              <span className='absolute left-1 top-1 rounded bg-primary px-2 py-0.5 text-[10px] font-semibold text-primary-foreground'>
                                Ảnh chính
                              </span>
                            )}

                            <button
                              type='button'
                              onClick={() =>
                                removeNewShoeImage(
                                  shoeNewPreviewUrls.indexOf(url)
                                )
                              }
                              className='absolute right-1 top-1 z-20 flex h-6 w-6 items-center justify-center rounded bg-destructive text-white'
                            >
                              <IconX size={14} />
                            </button>
                          </div>
                        </SortableImageItem>
                      );
                    })}

                    <button
                      type='button'
                      onClick={handleChooseMainImage}
                      className='flex aspect-square flex-col items-center justify-center gap-2 rounded-lg border border-dashed bg-muted/40 transition-colors hover:bg-muted/60'
                    >
                      <IconPlus className='h-6 w-6 text-muted-foreground' />
                      <span className='text-xs font-medium text-muted-foreground'>
                        {t(
                          'admin.products.addPage.images.addButton',
                          'Thêm ảnh'
                        )}
                      </span>
                    </button>
                  </div>
                </SortableContext>
              </DndContext>

              <div className='mt-2 text-xs text-muted-foreground'>
                {t(
                  'admin.products.addPage.imageDropzone.hint',
                  'Chọn nhiều ảnh, kéo thả để tải lên'
                )}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className='flex flex-row items-center justify-between'>
              <div>
                <CardTitle>
                  {t('admin.products.addPage.sections.variants')}
                </CardTitle>
                <p className='mt-1 text-xs text-muted-foreground'>
                  {t('admin.products.addPage.variants.subtitle')}
                </p>
              </div>
              <Button type='button' size='sm' onClick={handleAddVariant}>
                {t(
                  'admin.products.addPage.variants.addButton',
                  'Thêm biến thể'
                )}
              </Button>
            </CardHeader>
            <CardContent className='space-y-6'>
              {variants.map((variant, index) => (
                <div
                  key={variant.id}
                  className='rounded-lg border bg-card p-4 shadow-sm'
                >
                  <div className='mb-3 flex items-center justify-between'>
                    <p className='text-sm font-semibold'>
                      {t('admin.products.addPage.variants.itemTitle', {
                        index: index + 1,
                      })}
                    </p>
                    <Button
                      type='button'
                      variant='ghost'
                      size='sm'
                      className='text-destructive hover:text-destructive'
                      onClick={() => handleRemoveVariantAt(index)}
                      disabled={variants.length === 1}
                    >
                      <IconTrash className='mr-2 h-4 w-4' />
                      {t('common.delete')}
                    </Button>
                  </div>

                  <div className='grid gap-4 md:grid-cols-2'>
                    <div className='space-y-2'>
                      <Label htmlFor={`size-${variant.id}`}>
                        {t('admin.products.addPage.variants.fields.size.label')}
                      </Label>
                      <Input
                        id={`size-${variant.id}`}
                        value={variant.size}
                        onChange={handleVariantChange(variant.id, 'size')}
                        placeholder={t(
                          'admin.products.addPage.variants.fields.size.placeholder'
                        )}
                      />
                    </div>
                    <div className='space-y-2'>
                      <Label htmlFor={`color-${variant.id}`}>
                        {t(
                          'admin.products.addPage.variants.fields.color.label'
                        )}
                      </Label>
                      <Input
                        id={`color-${variant.id}`}
                        value={variant.color}
                        onChange={handleVariantChange(variant.id, 'color')}
                        placeholder={t(
                          'admin.products.addPage.variants.fields.color.placeholder'
                        )}
                      />
                    </div>
                  </div>

                  <div className='grid gap-4 md:grid-cols-2 mt-4'>
                    <div className='space-y-2'>
                      <Label htmlFor={`stock-${variant.id}`}>
                        {t(
                          'admin.products.addPage.variants.fields.stock.label'
                        )}
                      </Label>
                      <Input
                        id={`stock-${variant.id}`}
                        type='number'
                        min={0}
                        value={variant.stockQuantity}
                        onChange={handleVariantChange(
                          variant.id,
                          'stockQuantity'
                        )}
                        placeholder={t(
                          'admin.products.addPage.variants.fields.stock.placeholder'
                        )}
                      />
                    </div>
                  </div>

                  <div className='mt-4 space-y-2'>
                    <Label>
                      {t('admin.products.addPage.variants.image.label')}
                    </Label>

                    <DndContext
                      sensors={sensors}
                      collisionDetection={closestCenter}
                      onDragEnd={handleVariantImagesDragEnd(variant.id)}
                    >
                      <SortableContext
                        items={[
                          ...variant.existingImageUrls.map(
                            (url) => `existing:${url}`
                          ),
                          ...variant.newPreviewUrls.map((url) => `new:${url}`),
                        ]}
                        strategy={rectSortingStrategy}
                      >
                        <div className='grid grid-cols-3 gap-2 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6'>
                          {variant.existingImageUrls.map(
                            (url, existingIndex) => {
                              const isPrimary = existingIndex === 0;
                              return (
                                <SortableImageItem
                                  key={`existing:${url}`}
                                  id={`existing:${url}`}
                                >
                                  <div className='group relative aspect-square overflow-hidden rounded-md border border-primary bg-muted'>
                                    <img
                                      src={url}
                                      alt={`Variant ${index} existing`}
                                      className='h-full w-full object-cover'
                                    />

                                    {isPrimary && (
                                      <span className='absolute left-0.5 top-0.5 rounded bg-primary px-1 py-0.5 text-[10px] font-semibold text-primary-foreground'>
                                        Ảnh chính
                                      </span>
                                    )}

                                    <button
                                      type='button'
                                      onClick={() =>
                                        removeVariantExistingImage(
                                          variant.id,
                                          url
                                        )
                                      }
                                      className='absolute right-0.5 top-0.5 z-20 flex h-5 w-5 items-center justify-center rounded bg-destructive text-white'
                                    >
                                      <IconX size={12} />
                                    </button>
                                  </div>
                                </SortableImageItem>
                              );
                            }
                          )}

                          {variant.newPreviewUrls.map((url) => {
                            const mergedIndex =
                              variant.existingImageUrls.length +
                              variant.newPreviewUrls.indexOf(url);
                            const isPrimary = mergedIndex === 0;
                            return (
                              <SortableImageItem
                                key={`new:${url}`}
                                id={`new:${url}`}
                              >
                                <div className='group relative aspect-square overflow-hidden rounded-md border bg-muted'>
                                  <img
                                    src={url}
                                    alt={`Variant ${index} new`}
                                    className='h-full w-full object-cover'
                                  />

                                  {isPrimary && (
                                    <span className='absolute left-0.5 top-0.5 rounded bg-primary px-1 py-0.5 text-[10px] font-semibold text-primary-foreground'>
                                      Ảnh chính
                                    </span>
                                  )}

                                  <button
                                    type='button'
                                    onClick={() =>
                                      removeVariantNewImageByUrl(
                                        variant.id,
                                        url
                                      )
                                    }
                                    className='absolute right-0.5 top-0.5 z-20 flex h-5 w-5 items-center justify-center rounded bg-destructive text-white'
                                  >
                                    <IconX size={12} />
                                  </button>
                                </div>
                              </SortableImageItem>
                            );
                          })}

                          <label className='flex aspect-square cursor-pointer flex-col items-center justify-center gap-1 rounded-md border border-dashed bg-muted/40 transition-colors hover:bg-muted/60'>
                            <IconPlus className='h-4 w-4 text-muted-foreground' />
                            <span className='text-[10px] font-medium text-muted-foreground'>
                              {t(
                                'admin.products.addPage.variants.image.addButton',
                                'Ảnh'
                              )}
                            </span>
                            <input
                              type='file'
                              accept='image/*'
                              multiple
                              className='hidden'
                              onChange={(e) =>
                                handleVariantImageChange(variant.id, e)
                              }
                            />
                          </label>
                        </div>
                      </SortableContext>
                    </DndContext>
                  </div>
                </div>
              ))}
            </CardContent>
          </Card>
        </div>
      </form>

      <div className='sticky bottom-0 z-40 border-t bg-background/90 px-0 py-3 backdrop-blur'>
        <div className='flex items-center justify-end gap-2'>
          <Button variant='outline' onClick={handleCancel}>
            {t('common.cancel')}
          </Button>
          <Button onClick={handleSubmit} disabled={isSubmitting}>
            {t('common.save')}
          </Button>
        </div>
      </div>
    </div>
  );
}

