function getStatusVariant(
  status: string
): 'default' | 'secondary' | 'destructive' | 'outline' {
  switch (status) {
    case 'ACTIVE':
      return 'default';
    case 'OUT_OF_STOCK':
      return 'destructive';
    case 'INACTIVE':
    case 'DISCONTINUED':
      return 'secondary';
    case 'DRAFT':
    default:
      return 'outline';
  }
}

