function computeSummary(subtotal: number, itemCount: number) {
  const shipping = subtotal >= 100 ? 0 : 10;
  const tax = subtotal * 0.1;
  const total = subtotal + shipping + tax;
  return {
    subtotal,
    shipping,
    discount: 0,
    tax,
    total,
    itemCount,
  };
}

