    name: shoe.name,
    price: shoe.price,
    image:
      shoe.imageUrls?.length > 0
        ? (resolveImageUrl(shoe.imageUrls[0]) ?? FALLBACK_IMAGE)
        : FALLBACK_IMAGE,
    brand: shoe.brandName,
    createdAt: shoe.createdAt,
